import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'pdf']

def sanitize_filename(name):
    """Remove path traversal attempts but allow special chars in filenames."""
    cleaned = name.replace('..', '').replace('/', '').replace('\\', '')
    return cleaned

def get_format(filename):
    """Extract format from filename extension."""
    if '.' in filename:
        return filename.rsplit('.', 1)[1].lower()
    return None

@app.route('/api/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to requested format using ImageMagick."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file uploaded'}), 400

    uploaded = request.files['file']
    target_format = request.form.get('format', 'png').lower().strip()
    density = request.form.get('density', '150')
    resize = request.form.get('resize', '')

    if target_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Format not supported. Use: {ALLOWED_FORMATS}'}), 400

    # Validate density is numeric
    if not density.isdigit() or int(density) > 600:
        return jsonify({'error': 'Invalid density (1-600)'}), 400

    source_format = get_format(uploaded.filename)
    if source_format not in ALLOWED_FORMATS + ['svg', 'eps', 'tiff', 'bmp']:
        return jsonify({'error': 'Source format not recognized'}), 400

    with tempfile.TemporaryDirectory() as tmpdir:
        safe_name = sanitize_filename(uploaded.filename) or 'input.tmp'
        input_path = os.path.join(tmpdir, safe_name)
        output_path = os.path.join(tmpdir, f'output.{target_format}')

        uploaded.save(input_path)

        # Build ImageMagick convert command
        cmd = f'convert -density {density}'

        if resize:
            # Allow resize like "800x600", "50%", etc.
            cmd += f' -resize {resize}'

        cmd += f' "{input_path}" "{output_path}"'

        try:
            result = subprocess.run(
                cmd,
                shell=True,
                capture_output=True,
                timeout=30,
                cwd=tmpdir
            )

            if result.returncode != 0:
                stderr = result.stderr.decode('utf-8', errors='replace')[:500]
                return jsonify({'error': f'Conversion failed: {stderr}'}), 500

            if not os.path.exists(output_path):
                return jsonify({'error': 'Output file not generated'}), 500

            with open(output_path, 'rb') as f:
                content = f.read()

            return content, 200, {
                'Content-Type': f'image/{target_format}' if target_format != 'pdf' else 'application/pdf',
                'Content-Disposition': f'attachment; filename="converted.{target_format}"'
            }

        except subprocess.TimeoutExpired:
            return jsonify({'error': 'Conversion timed out'}), 504
        except Exception as e:
            return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
